import type { ExecArgs } from "@medusajs/framework/types"
import {
  ContainerRegistrationKeys,
  MedusaError,
} from "@medusajs/framework/utils"
import {
  createProductTagsWorkflow,
  updateProductsWorkflow,
} from "@medusajs/medusa/core-flows"
import { readFileSync } from "node:fs"
import { resolve } from "node:path"

type EnrichedProduct = {
  handle: string
  title: string
  subtitle: string
  description: string
  thumbnail: string
  images: string[]
  brand: string
  metadata: Record<string, unknown>
}

const BATCH = 25

/**
 * Applies sgnova/catalog/products.enriched.json (generated by
 * sgnova/catalog/tools/enrich_catalog.py) to the existing SGNova products.
 * Idempotent: products whose title, thumbnail and spec revision already match
 * are skipped. SGNOVA_FORCE=1 rewrites everything.
 *
 * Image URLs: the illustrations live in the storefront's /public/catalog.
 * SGNOVA_IMAGE_BASE_URL (the storefront's public origin, e.g.
 * https://shop.example.com) makes them absolute so the Medusa Admin, which
 * runs on the backend origin, can preview them. Rerun with the production
 * origin after deploying the storefront. Without it, paths stay relative.
 */
export default async function enrichSGNova({ container }: ExecArgs) {
  const logger = container.resolve(ContainerRegistrationKeys.LOGGER)
  const query = container.resolve(ContainerRegistrationKeys.QUERY)
  const force = process.env.SGNOVA_FORCE === "1"
  const imageBase = (process.env.SGNOVA_IMAGE_BASE_URL ?? "").replace(/\/$/, "")
  if (imageBase && !/^https?:\/\//.test(imageBase)) {
    throw new MedusaError(
      MedusaError.Types.INVALID_DATA,
      "SGNOVA_IMAGE_BASE_URL must be an absolute http(s) origin"
    )
  }
  const imageUrl = (path: string) =>
    imageBase && path.startsWith("/") ? `${imageBase}${path}` : path

  const dataPath = resolve(process.cwd(), "../../sgnova/catalog/products.enriched.json")
  const fixtures: EnrichedProduct[] = (
    JSON.parse(readFileSync(dataPath, "utf8")) as EnrichedProduct[]
  ).map((f) => ({
    ...f,
    thumbnail: imageUrl(f.thumbnail),
    images: f.images.map(imageUrl),
  }))
  if (fixtures.length < 500) {
    throw new MedusaError(
      MedusaError.Types.INVALID_DATA,
      `Expected at least 500 fixtures, found ${fixtures.length}`
    )
  }

  // Brand tags power the brand facet in search (indexed as `labels`).
  const brands = [...new Set(fixtures.map((f) => f.brand))]
  const { data: tags } = await query.graph({
    entity: "product_tag",
    fields: ["id", "value"],
  })
  const missingBrands = brands.filter((b) => !tags.some((t) => t.value === b))
  if (missingBrands.length) {
    await createProductTagsWorkflow(container).run({
      input: { product_tags: missingBrands.map((value) => ({ value })) },
    })
    logger.info(`Created brand tags: ${missingBrands.join(", ")}`)
  }
  const { data: allTags } = await query.graph({
    entity: "product_tag",
    fields: ["id", "value"],
  })
  const tagId = new Map(allTags.map((t) => [t.value, t.id]))

  const { data: products } = await query.graph({
    entity: "product",
    fields: ["id", "handle", "title", "thumbnail", "metadata", "tags.id"],
    filters: { handle: fixtures.map((f) => f.handle) },
  })
  const byHandle = new Map(products.map((p) => [p.handle, p]))

  const missing = fixtures.filter((f) => !byHandle.has(f.handle))
  if (missing.length) {
    throw new MedusaError(MedusaError.Types.NOT_FOUND, `Products missing in Medusa: ${missing.slice(0, 5).map((m) => m.handle).join(", ")}`)
  }

  const pending = fixtures.filter((f) => {
    const p = byHandle.get(f.handle)!
    const specs = (p.metadata as Record<string, unknown> | null)?.specs
    return (
      force ||
      p.title !== f.title ||
      p.thumbnail !== f.thumbnail ||
      JSON.stringify(specs) !== JSON.stringify(f.metadata.specs)
    )
  })
  logger.info(`Enrichment: ${pending.length} to update, ${fixtures.length - pending.length} already current`)

  for (let i = 0; i < pending.length; i += BATCH) {
    const batch = pending.slice(i, i + BATCH)
    await updateProductsWorkflow(container).run({
      input: {
        products: batch.map((f) => {
          const p = byHandle.get(f.handle)!
          const brandTag = tagId.get(f.brand)
          const tagIds = new Set((p.tags ?? []).map((t) => t!.id))
          if (brandTag) tagIds.add(brandTag)
          return {
            id: p.id,
            title: f.title,
            subtitle: f.subtitle,
            description: f.description,
            thumbnail: f.thumbnail,
            images: f.images.map((url) => ({ url })),
            tag_ids: [...tagIds],
            metadata: f.metadata,
          }
        }),
      },
    })
    logger.info(`Enriched ${Math.min(i + BATCH, pending.length)}/${pending.length}`)
  }

  // Verification pass.
  const { data: after } = await query.graph({
    entity: "product",
    fields: ["id", "thumbnail", "metadata"],
    filters: { handle: fixtures.map((f) => f.handle) },
  })
  const withImage = after.filter((p) => Boolean(p.thumbnail)).length
  const withSpecs = after.filter((p) => Array.isArray((p.metadata as any)?.specs)).length
  logger.info(`SGNOVA ENRICH: products=${after.length} thumbnails=${withImage} specs=${withSpecs}`)
  if (withImage !== fixtures.length || withSpecs !== fixtures.length) {
    throw new MedusaError(
      MedusaError.Types.UNEXPECTED_STATE,
      "Enrichment verification failed"
    )
  }
}
